/*
 * A082853  Integers 0 to Catalan(n)-1 followed by integers 0 to
 *          Catalan(n+1)-1 etc.
 * https://oeis.org/A082853
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n - A082852(n) where A082852(n) = Σ_{k=0}^{m-1}
 *            Catalan(k), m chosen such that Σ_{k=0}^{m} Catalan(k) > n.
 *            Catalan numbers are generated by recurrence C_{k+1} = C_k *
 *            2*(2k+1) / (k+2)
 * Range:     u8 n <= 296, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    seq_t cumulative = 0;   /* Sum of Catalan numbers of previous blocks */
    seq_t cat        = 1;   /* Catalan(0) */
    idx_t k          = 0;   /* Current block index */

    for ( ;; ) {
        seq_t next_cumulative = cumulative + cat;
        if ( next_cumulative > (seq_t)n ) {
            /* n lies inside the current block; value is offset within block */
            return (seq_t)n - cumulative;
        }
        /* advance to the next block */
        cumulative = next_cumulative;
        cat = cat * ((seq_t)2 * (seq_t)(2 * k + 1)) / ((seq_t)(k + 2));
        ++k;
    }
}
